import fs from 'node:fs/promises'
import {dir,db,asset,send,reviewed,task} from './reply-runtime-20261007.mjs'
const s=JSON.parse(await fs.readFile(dir+'/reply-review.json','utf8'))
const plans=[]
function add(name,body,extra={}){const c=s.contacts.find(c=>c.name===name);const thread=s.touches.filter(t=>t.contact_id===c.id);plans.push({id:c.id,name,phone:c.phone,city:c.city,latest:thread.at(-1).id,from:'+14374650584',body,...extra})}
for(const name of ['TAHIR NADEEM','NICHOLAS ZOGRAFOS','MIKE WITT','VANI JEYAKANTHAN']){const c=s.contacts.find(c=>c.name===name),first=name.split(' ')[0].toLowerCase().replace(/^./,x=>x.toUpperCase());add(name,`Here you go, ${first}! Here's our ${c.city} card. Feel free to save it and share it when a client needs moving help.`,{media_urls:[await asset(c.city)]})}
add('Elva Meadows',"Hi Elva! We provide binding estimates once the move details are confirmed. Pricing depends on the inventory, pickup and delivery locations, distance, stairs or elevator access, and any packing needed. If you have a particular move in mind, send me the date, route and rough inventory and we can work out an estimate.",{note:'Answered general rate question with approved estimate factors. No numeric rate invented; no live job assumed.'})
add('DAVID LIU',"Thanks David! Just checking the spelling before I send anything: did you mean DavidLiuTorontoRealtor@gmail.com? The address came through with gamil.com.",{note:'Recipient supplied gamil.com address; requested confirmation before email, did not silently correct or send to unverified address.'})
const card=await asset('Mississauga')
add('Anita Pall',`Hi Anita,\n\nThanks for getting back to me! I'm John Owolabi from Saturn Star Movers. We've been in business for over seven years and help with moves in Mississauga and surrounding areas, as well as the wider GTA, Hamilton and Southwestern Ontario.\n\nHere's our Mississauga digital card for you to save or forward when a client needs moving help:\n${card}\n\nClients can call or text 437-782-3004 or email mississauga@starmovers.ca for a moving quote. We provide binding estimates once the move details are confirmed, based on the inventory, route, access and any packing needed.\n\nWebsite: https://starmovers.ca\n\nLooking forward to working together,\nJohn Owolabi\nSaturn Star Movers`,{channel:'email',email:'anita@thefreshapproach.ca',subject:'Your Saturn Star Movers card and details - Mississauga',note:'Requested company introduction and Mississauga card link sent by SES to recipient-supplied address.'})
await fs.writeFile(dir+'/reply-plan.json',JSON.stringify(plans,null,2))
if(!process.argv.includes('--send')){console.log(JSON.stringify(plans,null,2));process.exit(0)}
for(const p of plans.filter(p=>p.channel!=='email'))await send(p)
const david=s.contacts.find(c=>c.name==='DAVID LIU');await task(david,'20261007-david-email','Confirm David Liu’s email spelling','Recipient supplied DavidLiuTorontoRealtor@gamil.com. Asked whether gmail.com was intended. Await confirmation before sending Toronto card/details by email.')
for(const c of s.contacts){if(plans.some(p=>p.id===c.id)||c.name==='VIDUR ARORA')continue;const last=s.touches.filter(t=>t.contact_id===c.id).at(-1);if(last?.direction!=='inbound')continue;const [fresh]=await db('market_touches',{contact_id:'eq.'+c.id,order:'created_at.desc,id.desc',limit:'1'});if(fresh.id===last.id)await reviewed(last.id,'Thanks/reaction or saved-contact acknowledgement reviewed. No extra outbound needed. Existing fulfilment tasks retained.')}
console.log(JSON.stringify({sms:6,email_prepared:1}))
